import { existsSync, readdirSync, readFileSync, statSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";

/* The hosted guide's backend carries its own copy of the corpus (backend/ask/corpus.json) and readable passage files (backend/kb-data).
 * Both are generated by `npm run rag:export`. This keeps the copy from drifting from what the site shows, and keeps secrets out of backend/. */
const site = JSON.parse(readFileSync("src/generated/corpus.json", "utf8")) as { passages: { id: string }[] };

describe("backend retrieval corpus", () => {
  it("is the site's corpus (rerun `npm run rag:export` after changing content)", () => {
    expect(existsSync("backend/ask/corpus.json")).toBe(true);
    expect(JSON.parse(readFileSync("backend/ask/corpus.json", "utf8"))).toEqual(site);
  });
  it("has one readable file per passage and no others", () => {
    const files = readdirSync("backend/kb-data").sort();
    expect(files).toEqual(site.passages.map((p) => `${p.id}.txt`).sort());
  });
});

describe("backend holds no secrets", () => {
  const walk = (d: string): string[] => readdirSync(d).flatMap((n) => { const p = join(d, n); return statSync(p).isDirectory() ? (n === "node_modules" ? [] : walk(p)) : [p]; });
  it("has no API key, access key or inline secret value", () => {
    const hits = walk("backend").filter((f) => /gsk_[A-Za-z0-9]{20,}|AKIA[0-9A-Z]{16}|"?(api[_-]?key|secret)"?\s*[:=]\s*["'][A-Za-z0-9_\-]{16,}["']/i.test(readFileSync(f, "utf8")));
    expect(hits).toEqual([]);
  });
});
